effect.shader:
// Star Tunnel - camera pose + auto motion blur (based on @P_Malin)
// AM official style: fixed loops, only builtins

float Random(float x){
  return fract(sin(x * 123.456) * 23.4567 + sin(x * 345.678) * 45.6789 + sin(x * 456.789) * 56.789);
}

vec3 RotateX(vec3 v, float a){ float s=sin(a), c=cos(a); return vec3(v.x, c*v.y + s*v.z, -s*v.y + c*v.z); }
vec3 RotateY(vec3 v, float a){ float s=sin(a), c=cos(a); return vec3(c*v.x + s*v.z, v.y, -s*v.x + c*v.z); }
vec3 RotateZ(vec3 v, float a){ float s=sin(a), c=cos(a); return vec3(c*v.x + s*v.y, -s*v.x + c*v.y, v.z); }

// Tunables (kept as constants for stability)
const float fSteps = 121.0;
const float fMinDist = 0.8;
const float fMaxDist = 5.0;
const float fRepeatMin = 1.0;
const float fRepeatMax = 2.0;
const float fDepthFade = 0.8;

vec3 GetParticlePos(vec3 vRayDir, float fZPos, float fSeed){
  float fAngle = atan(vRayDir.x, vRayDir.y);
  float fAngleFraction = fract(fAngle / (6.28318530718));
  float fSegment = floor(fAngleFraction * fSteps + fSeed) + 0.5 - fSeed;
  float fParticleAngle = fSegment / fSteps * (6.28318530718);
  float fSegmentPos = fSegment / fSteps;
  float fRadius = fMinDist + Random(fSegmentPos + fSeed) * (fMaxDist - fMinDist);
  float tunnelZ = vRayDir.z / length(vRayDir.xy / fRadius);
  tunnelZ += fZPos;
  float fRepeat = fRepeatMin + Random(fSegmentPos + 0.1 + fSeed) * (fRepeatMax - fRepeatMin);
  float fParticleZ = (ceil(tunnelZ / fRepeat) - 0.5) * fRepeat - fZPos;
  return vec3( sin(fParticleAngle) * fRadius, cos(fParticleAngle) * fRadius, fParticleZ );
}

vec3 GetParticleColour(vec3 vParticlePos, float fParticleSize, vec3 vRayDir, float particleLength, float brightness){
  vec2 vNormDir = normalize(vRayDir.xy);
  float d1 = dot(vParticlePos.xy, vNormDir.xy) / max(length(vRayDir.xy), 1e-5);
  vec3 vClosest2d = vRayDir * d1;
  vec3 vClampedPos = vParticlePos;
  vClampedPos.z = clamp(vClosest2d.z, vParticlePos.z - particleLength, vParticlePos.z + particleLength);
  float d = dot(vClampedPos, vRayDir);
  vec3 vClosestPos = vRayDir * d;
  vec3 vDeltaPos = vClampedPos - vClosestPos;
  float fClosestDist = length(vDeltaPos) / max(fParticleSize, 1e-5);
  float fShade = clamp(1.0 - fClosestDist, 0.0, 1.0);
  fShade = fShade * exp2(-d * fDepthFade) * brightness;
  return vec3(fShade);
}

vec4 GetParticleEx(vec3 vRayDir, float fZPos, float fSeed){
  float fAngle = atan(vRayDir.x, vRayDir.y);
  float fAngleFraction = fract(fAngle / (6.28318530718));
  float fSegment = floor(fAngleFraction * fSteps + fSeed) + 0.5 - fSeed;
  float fParticleAngle = fSegment / fSteps * (6.28318530718);
  float fSegmentPos = fSegment / fSteps;
  float fRadius = fMinDist + Random(fSegmentPos + fSeed) * (fMaxDist - fMinDist);
  float tunnelZ = vRayDir.z / length(vRayDir.xy / fRadius);
  tunnelZ += fZPos;
  float fRepeat = fRepeatMin + Random(fSegmentPos + 0.1 + fSeed) * (fRepeatMax - fRepeatMin);
  float fRing = (ceil(tunnelZ / fRepeat) - 0.5);
  float fParticleZ = fRing * fRepeat - fZPos;
  float id = floor(fSegment) + 4096.0 * floor(fRing);
  vec3 pos = vec3( sin(fParticleAngle) * fRadius, cos(fParticleAngle) * fRadius, fParticleZ );
  return vec4(pos, id);
}

vec3 Starfield(vec3 vRayDir, float fZPos, float fSeed, float fParticleSize, float particleLength, float brightness){
  vec3 sysRad = radians(sysRotDeg);
  float ax = sysRad.x + radians(sysRotSpeedX) * acTime;
  float ay = sysRad.y + radians(sysRotSpeedY) * acTime;
  float az = sysRad.z + radians(sysRotSpeedZ) * acTime;
  vec3 vRayObj = vRayDir;
  vRayObj = RotateX(vRayObj, -ax);
  vRayObj = RotateY(vRayObj, -ay);
  vRayObj = RotateZ(vRayObj, -az);
  vec4 P = GetParticleEx(vRayObj, fZPos, fSeed);
  vec3 vParticlePos = P.xyz;
  float pid = P.w;
  vec3 shade = GetParticleColour(vParticlePos, fParticleSize, vRayObj, particleLength, brightness);
  float h = fract(sin(pid*123.456 + fSeed*7.123) * 43758.5453);
  vec3 c = (h < 0.5) ? colorA.rgb : colorB.rgb;
  return shade * c;
}

void main(){
  // Screen ray
  vec2 vScreenUV = acScreenNorm;
  vec2 vScreenPos = vScreenUV * 2.0 - 1.0;
  vScreenPos.x *= acScreenSize.x / max(acScreenSize.y, 1.0);
  // Camera XY offsets: shift screen pos (parallax-like)
  vScreenPos += vec2(camX, camY) * 0.2;

  vec3 vRayDir = normalize(vec3(vScreenPos, 1.0));

  // Apply rotations
  vec3 rotRad = radians(rotDeg);
  float rx = rotRad.x;
  float ry = rotRad.y;
  float rz = rotRad.z;
  vRayDir = RotateX(vRayDir, rx);
  vRayDir = RotateY(vRayDir, ry);
  vRayDir = RotateZ(vRayDir, rz);

  // Forward motion controlled by zSpeed and camZ offset
  float t = acTime;
  float fZPos = camZ + t * zSpeed;
  float fSpeed = abs(zSpeed);

  // Auto motion-blur -> particle trail length (includes rotation-driven blur)
  float rotComponent = rotBlurSpeed * 0.002; // deg/s to trail scalar
  float particleLength = autoBlur ? (blurFactor * (fSpeed + rotComponent + 0.001)) : manualTrail; // in Z units

  // No background: start from black for transparent background
  vec3 vResult = vec3(0.0);

  // Pass count (1..3 capped)
  int passes = int(clamp(float(particleCount), 1.0, 3.0));
  float fSeed = 0.0;
  for(int i=0;i<3;i++){
    if(i>=passes) break;
    vResult += Starfield(vRayDir, fZPos, fSeed, particleSize, particleLength, brightness);
    fSeed += 1.234;
  }

  vec3 col = sqrt(vResult);
  // Alpha derived from star intensity (transparent background)
  float starIntensity = max(max(col.r, col.g), col.b);
  float aOut = clamp(starIntensity, 0.0, 1.0) * alpha;
  gl_FragColor = vec4(col, aOut);
}
